// STOMP client minified
var Stomp={over:function(a){return new StompClient(a)}};function StompClient(a){this.ws=a;this.callbacks={};this.subs={};this.counter=0;this.connected=!1}return StompClient.prototype.connect=function(a,b,c){var d=this;this.callbacks=b||{};this.ws.onmessage=function(a){var b=JSON.parse(a.data);d.callbacks[b.type]&&d.callbacks[b.type](b)};this.ws.onopen=function(){d.connected=!0;c&&c()};this.ws.onclose=function(){d.connected=!1};this.ws.send(JSON.stringify({command:"CONNECT",headers:{}}))},StompClient.prototype.subscribe=function(a,b){var c="sub-"+this.counter++;this.subs[c]=b;return this.ws.send(JSON.stringify({command:"SUBSCRIBE",headers:{destination:a,id:c}})),c},StompClient.prototype.send=function(a,b,c){this.ws.send(JSON.stringify({command:"SEND",headers:{destination:a},body:JSON.stringify(c)}))},StompClient.prototype.disconnect=function(){this.ws.close()}; // Placeholder - full STOMP.js needed
